const input = $json || {};
const recommendations = Array.isArray(input.recommendations)
  ? input.recommendations
  : [];

const context = input.context || {};
const derived =
  context.derivedContext ||
  context.derived ||
  {};

const userState = context.userState || {};
const metadata = input.metadata || {};

const clamp10 = value =>
  Math.max(0, Math.min(10, Number(value ?? 0)));

const clamp100 = value =>
  Math.max(0, Math.min(100, Math.round(Number(value ?? 0))));

const defaultWeights = {
  datingOpportunity: 20,
  socialCircleGrowth: 20,
  nightlifeValue: 10,
  travelValue: 10,
  healthImpact: 10,
  newExperience: 10,
  funFactor: 8,
  confidenceGrowth: 5,
  careerValue: 3,
  learningValue: 2,
  costEfficiency: 2
};

const categoryProfiles = {
  social: {
    datingOpportunity: 8,
    socialCircleGrowth: 10,
    nightlifeValue: 5,
    travelValue: 1,
    healthImpact: 2,
    newExperience: 7,
    funFactor: 8,
    confidenceGrowth: 9,
    careerValue: 5,
    learningValue: 3,
    costEfficiency: 6
  },
  dating: {
    datingOpportunity: 10,
    socialCircleGrowth: 8,
    nightlifeValue: 6,
    travelValue: 1,
    healthImpact: 1,
    newExperience: 8,
    funFactor: 8,
    confidenceGrowth: 10,
    careerValue: 1,
    learningValue: 3,
    costEfficiency: 5
  },
  nightlife: {
    datingOpportunity: 9,
    socialCircleGrowth: 8,
    nightlifeValue: 10,
    travelValue: 1,
    healthImpact: 1,
    newExperience: 7,
    funFactor: 10,
    confidenceGrowth: 8,
    careerValue: 2,
    learningValue: 1,
    costEfficiency: 4
  },
  travel: {
    datingOpportunity: 5,
    socialCircleGrowth: 6,
    nightlifeValue: 4,
    travelValue: 10,
    healthImpact: 5,
    newExperience: 10,
    funFactor: 9,
    confidenceGrowth: 7,
    careerValue: 3,
    learningValue: 7,
    costEfficiency: 4
  },
  fitness: {
    datingOpportunity: 3,
    socialCircleGrowth: 5,
    nightlifeValue: 1,
    travelValue: 1,
    healthImpact: 10,
    newExperience: 5,
    funFactor: 6,
    confidenceGrowth: 9,
    careerValue: 1,
    learningValue: 4,
    costEfficiency: 8
  },
  wellness: {
    datingOpportunity: 2,
    socialCircleGrowth: 3,
    nightlifeValue: 1,
    travelValue: 1,
    healthImpact: 10,
    newExperience: 4,
    funFactor: 5,
    confidenceGrowth: 6,
    careerValue: 1,
    learningValue: 3,
    costEfficiency: 8
  },
  style: {
    datingOpportunity: 7,
    socialCircleGrowth: 5,
    nightlifeValue: 3,
    travelValue: 1,
    healthImpact: 3,
    newExperience: 5,
    funFactor: 4,
    confidenceGrowth: 10,
    careerValue: 5,
    learningValue: 3,
    costEfficiency: 5
  },
  career: {
    datingOpportunity: 2,
    socialCircleGrowth: 6,
    nightlifeValue: 1,
    travelValue: 2,
    healthImpact: 1,
    newExperience: 6,
    funFactor: 4,
    confidenceGrowth: 6,
    careerValue: 10,
    learningValue: 9,
    costEfficiency: 7
  },
  learning: {
    datingOpportunity: 1,
    socialCircleGrowth: 4,
    nightlifeValue: 1,
    travelValue: 1,
    healthImpact: 2,
    newExperience: 6,
    funFactor: 4,
    confidenceGrowth: 5,
    careerValue: 7,
    learningValue: 10,
    costEfficiency: 8
  },
  finance: {
    datingOpportunity: 1,
    socialCircleGrowth: 1,
    nightlifeValue: 1,
    travelValue: 2,
    healthImpact: 2,
    newExperience: 2,
    funFactor: 2,
    confidenceGrowth: 4,
    careerValue: 5,
    learningValue: 7,
    costEfficiency: 10
  },
  general: {
    datingOpportunity: 4,
    socialCircleGrowth: 5,
    nightlifeValue: 3,
    travelValue: 3,
    healthImpact: 4,
    newExperience: 5,
    funFactor: 5,
    confidenceGrowth: 5,
    careerValue: 4,
    learningValue: 4,
    costEfficiency: 5
  }
};

const getProfile = category => {
  const key = String(category || 'general').toLowerCase();

  if (categoryProfiles[key]) return { ...categoryProfiles[key] };

  if (key.includes('social') || key.includes('network')) {
    return { ...categoryProfiles.social };
  }

  if (key.includes('night')) {
    return { ...categoryProfiles.nightlife };
  }

  if (key.includes('travel') || key.includes('trip')) {
    return { ...categoryProfiles.travel };
  }

  if (key.includes('fitness') || key.includes('sport')) {
    return { ...categoryProfiles.fitness };
  }

  return { ...categoryProfiles.general };
};

const enrichFromRawScores = (profile, rawScores = {}) => {
  const result = { ...profile };

  if (rawScores.organicConnectionPotential !== undefined) {
    result.datingOpportunity =
      (result.datingOpportunity + clamp10(rawScores.organicConnectionPotential)) / 2;
  }

  if (rawScores.socialQuality !== undefined) {
    result.socialCircleGrowth =
      (result.socialCircleGrowth + clamp10(rawScores.socialQuality)) / 2;
  }

  if (rawScores.funNovelty !== undefined) {
    result.newExperience =
      (result.newExperience + clamp10(rawScores.funNovelty)) / 2;

    result.funFactor =
      (result.funFactor + clamp10(rawScores.funNovelty)) / 2;
  }

  if (rawScores.fitnessValue !== undefined) {
    result.healthImpact =
      (result.healthImpact + clamp10(rawScores.fitnessValue)) / 2;
  }

  if (rawScores.growthValue !== undefined) {
    result.confidenceGrowth =
      (result.confidenceGrowth + clamp10(rawScores.growthValue)) / 2;

    result.learningValue =
      (result.learningValue + clamp10(rawScores.growthValue)) / 2;
  }

  if (rawScores.networkingValue !== undefined) {
    result.careerValue =
      (result.careerValue + clamp10(rawScores.networkingValue)) / 2;
  }

  if (rawScores.valueForMoney !== undefined) {
    result.costEfficiency =
      (result.costEfficiency + clamp10(rawScores.valueForMoney)) / 2;
  }

  return result;
};

const applyContextAdjustments = (scores, recommendation) => {
  const adjusted = { ...scores };
  const reasons = [];

  const category = String(recommendation.category || '').toLowerCase();

  if (
    derived.needsMoreSocial === true &&
    ['social', 'dating', 'nightlife', 'networking'].some(value =>
      category.includes(value)
    )
  ) {
    adjusted.socialCircleGrowth += 1;
    adjusted.datingOpportunity += 0.5;
    reasons.push('Social activity is below the weekly target.');
  }

  if (
    derived.needsMoreFitness === true &&
    ['fitness', 'sports', 'wellness'].some(value =>
      category.includes(value)
    )
  ) {
    adjusted.healthImpact += 1;
    adjusted.confidenceGrowth += 0.5;
    reasons.push('Fitness activity is below the weekly target.');
  }

  if (
    derived.isWeekend === true &&
    ['travel', 'social', 'nightlife', 'dating'].some(value =>
      category.includes(value)
    )
  ) {
    adjusted.funFactor += 0.5;
    adjusted.newExperience += 0.5;
    reasons.push('Weekend timing improves suitability.');
  }

  if (
    derived.calendarLoad === 'high' &&
    !['wellness', 'recovery'].some(value =>
      category.includes(value)
    )
  ) {
    adjusted.funFactor -= 1;
    adjusted.healthImpact -= 0.5;
    reasons.push('High calendar load reduces life impact.');
  }

  const energy = String(userState.energyLevel || '').toLowerCase();

  if (
    energy === 'high' &&
    ['social', 'dating', 'nightlife', 'travel', 'fitness'].some(value =>
      category.includes(value)
    )
  ) {
    adjusted.funFactor += 0.5;
    adjusted.confidenceGrowth += 0.5;
    reasons.push('Current energy level supports an active plan.');
  }

  if (
    energy === 'low' &&
    ['nightlife', 'travel', 'fitness'].some(value =>
      category.includes(value)
    )
  ) {
    adjusted.funFactor -= 1.5;
    adjusted.healthImpact -= 0.5;
    reasons.push('Low energy reduces suitability.');
  }

  const budgetAED = Number(userState.budgetAED);

  if (
    Number.isFinite(budgetAED) &&
    recommendation.estimatedCost !== null &&
    recommendation.estimatedCost !== undefined
  ) {
    const cost = Number(recommendation.estimatedCost);

    if (Number.isFinite(cost)) {
      if (cost <= budgetAED) {
        adjusted.costEfficiency += 0.5;
        reasons.push('Estimated cost is within the current budget.');
      } else {
        const overRatio = cost / Math.max(1, budgetAED);
        adjusted.costEfficiency -= Math.min(3, overRatio);
        reasons.push('Estimated cost exceeds the current budget.');
      }
    }
  }

  for (const key of Object.keys(adjusted)) {
    adjusted[key] = clamp10(adjusted[key]);
  }

  return { adjusted, reasons };
};

const calculateWeightedScore = scores => {
  let total = 0;

  for (const [criterion, weight] of Object.entries(defaultWeights)) {
    total += clamp10(scores[criterion]) * weight;
  }

  return clamp100(total / 10);
};

const scored = recommendations.map((recommendation, index) => {
  const baseProfile = getProfile(recommendation.category);
  const enrichedProfile = enrichFromRawScores(
    baseProfile,
    recommendation.rawScores || {}
  );

  const { adjusted, reasons } =
    applyContextAdjustments(enrichedProfile, recommendation);

  const lifeImpactScore =
    calculateWeightedScore(adjusted);

  const eventScore =
    clamp100(
      recommendation.eventScore ??
      recommendation.score ??
      0
    );

  const personalFitScore =
    clamp100(
      (
        clamp10(recommendation.rawScores?.audienceFit ?? 5) * 3 +
        clamp10(recommendation.rawScores?.soloFriendly ?? 5) * 2 +
        clamp10(recommendation.rawScores?.calendarCompatibility ?? 5) * 3 +
        clamp10(recommendation.rawScores?.travelConvenience ?? 5) * 2
      )
    );

  const confidence =
    Math.max(
      0,
      Math.min(1, Number(recommendation.confidence ?? 0.5))
    );

  const confidenceScore =
    clamp100(confidence * 100);

  const finalScore = clamp100(
    eventScore * 0.30 +
    lifeImpactScore * 0.40 +
    personalFitScore * 0.20 +
    confidenceScore * 0.10
  );

  const lifeClassification =
    finalScore >= 90 ? 'Transformative Opportunity' :
    finalScore >= 80 ? 'High Life Impact' :
    finalScore >= 70 ? 'Strong Life Fit' :
    finalScore >= 55 ? 'Useful Option' :
    'Low Priority';

  return {
    ...recommendation,
    originalRank: recommendation.rank || index + 1,
    eventScore,
    lifeImpactScore,
    personalFitScore,
    confidenceScore,
    finalScore,
    lifeClassification,
    lifeImpactBreakdown: adjusted,
    lifeImpactReasons: reasons
  };
});

const ranked = scored
  .sort((a, b) => {
    if (b.finalScore !== a.finalScore) {
      return b.finalScore - a.finalScore;
    }

    return b.lifeImpactScore - a.lifeImpactScore;
  })
  .map((item, index) => ({
    lifeRank: index + 1,
    ...item
  }));

const topLifeOpportunities = ranked.slice(0, 5);

const priorityMix = {
  datingAndSocial:
    ranked.filter(item =>
      ['social', 'dating', 'nightlife', 'networking'].some(value =>
        String(item.category || '').toLowerCase().includes(value)
      )
    ).length,
  travel:
    ranked.filter(item =>
      String(item.category || '').toLowerCase().includes('travel')
    ).length,
  fitness:
    ranked.filter(item =>
      ['fitness', 'sports', 'wellness'].some(value =>
        String(item.category || '').toLowerCase().includes(value)
      )
    ).length,
  careerAndLearning:
    ranked.filter(item =>
      ['career', 'learning'].some(value =>
        String(item.category || '').toLowerCase().includes(value)
      )
    ).length
};

return [{
  json: {
    success: true,
    result: {
      recommendationCount: recommendations.length,
      topLifeOpportunities,
      allLifeScoredRecommendations: ranked,
      priorityMix,
      scoringWeights: defaultWeights
    },
    memoryUpdates: topLifeOpportunities.map(item => ({
      type: 'life_impact_score',
      operation: 'append',
      payload: {
        recommendationId: item.id,
        title: item.title,
        category: item.category,
        eventScore: item.eventScore,
        lifeImpactScore: item.lifeImpactScore,
        personalFitScore: item.personalFitScore,
        finalScore: item.finalScore,
        lifeClassification: item.lifeClassification,
        createdAt: new Date().toISOString()
      }
    })),
    approvalRequests: [],
    logs: [{
      timestamp: new Date().toISOString(),
      workflow: 'Concierge OS - Life Impact Scoring Engine',
      level: 'info',
      correlationId: metadata.correlationId || '',
      message:
        `Calculated life impact for ${ranked.length} recommendations.`,
      details: {
        recommendationCount: ranked.length,
        topRecommendation:
          ranked[0]
            ? {
                id: ranked[0].id,
                title: ranked[0].title,
                finalScore: ranked[0].finalScore
              }
            : null,
        priorityMix
      }
    }],
    nextAction: {
      type: 'build_life_strategy',
      targetWorkflow: 'Concierge OS - Life Strategy Engine'
    },
    error: null
  }
}];
